CREATE DATABASE Ventas_Tech_DB;
GO

USE Ventas_Tech_DB;
GO

----------------------------
-- Sección 1 — DROP TABLES
----------------------------
--
DROP TABLE IF EXISTS ventas;
DROP TABLE IF EXISTS productos;
DROP TABLE IF EXISTS subcategorias;
DROP TABLE IF EXISTS categorias;
DROP TABLE IF EXISTS canales;
DROP TABLE IF EXISTS clientes;
DROP TABLE IF EXISTS segmentos;
DROP TABLE IF EXISTS territorios;
DROP TABLE IF EXISTS zonas;
DROP TABLE IF EXISTS regiones;
DROP TABLE IF EXISTS paises;


----------------------------
-- Sección 2 — CREATE TABLES
----------------------------
-- 
CREATE TABLE [Paises] (
  [id_pais] int PRIMARY KEY,
  [pais] varchar(50)
)
GO

CREATE TABLE [Regiones] (
  [id_region] int PRIMARY KEY,
  [region] varchar(50),
  [id_pais] int NOT NULL
)
GO

CREATE TABLE [Zonas] (
  [id_zona] int PRIMARY KEY,
  [zona] varchar(60),
  [id_region] int NOT NULL
)
GO

CREATE TABLE [Territorios] (
  [id_territorio] int PRIMARY KEY,
  [id_zona] int NOT NULL
)
GO

CREATE TABLE [Clientes] (
  [id_cliente] int PRIMARY KEY,
  [nombre] varchar(100),
  [email] varchar(150) UNIQUE,
  [ciudad] varchar(100),
  [id_segmento] int NOT NULL,
  [fecha_registro] date,
  [id_territorio] int NOT NULL
)
GO

CREATE TABLE [Categorias] (
  [id_categoria] int PRIMARY KEY,
  [categoria] varchar(100)
)
GO

CREATE TABLE [Subcategorias] (
  [id_subcategoria] int PRIMARY KEY,
  [subcategoria] varchar(100),
  [id_categoria] int NOT NULL
)
GO

CREATE TABLE [Productos] (
  [id_producto] int PRIMARY KEY,
  [nombre_producto] varchar(150),
  [id_subcategoria] int NOT NULL,
  [precio] decimal(12,2),
  [costo] decimal(12,2)
)
GO

CREATE TABLE [Ventas] (
  [id_venta] int PRIMARY KEY,
  [fecha_venta] date,
  [id_cliente] int NOT NULL,
  [id_producto] int NOT NULL,
  [cantidad] int,
  [total_venta] decimal(12,2),
  [id_canal] int NOT NULL
)
GO

CREATE TABLE [Canales] (
  [id_canal] int PRIMARY KEY,
  [canal] varchar(50)
)
GO

CREATE TABLE [Segmentos] (
  [id_segmento] int PRIMARY KEY,
  [segmento] varchar(50)
)
GO

ALTER TABLE [Regiones] ADD FOREIGN KEY ([id_pais]) REFERENCES [Paises] ([id_pais])
GO

ALTER TABLE [Zonas] ADD FOREIGN KEY ([id_region]) REFERENCES [Regiones] ([id_region])
GO

ALTER TABLE [Territorios] ADD FOREIGN KEY ([id_zona]) REFERENCES [Zonas] ([id_zona])
GO

ALTER TABLE [Clientes] ADD FOREIGN KEY ([id_territorio]) REFERENCES [Territorios] ([id_territorio])
GO

ALTER TABLE [Clientes] ADD FOREIGN KEY ([id_segmento]) REFERENCES [Segmentos] ([id_segmento])
GO

ALTER TABLE [Subcategorias] ADD FOREIGN KEY ([id_categoria]) REFERENCES [Categorias] ([id_categoria])
GO

ALTER TABLE [Productos] ADD FOREIGN KEY ([id_subcategoria]) REFERENCES [Subcategorias] ([id_subcategoria])
GO

ALTER TABLE [Ventas] ADD FOREIGN KEY ([id_cliente]) REFERENCES [Clientes] ([id_cliente])
GO

ALTER TABLE [Ventas] ADD FOREIGN KEY ([id_producto]) REFERENCES [Productos] ([id_producto])
GO

ALTER TABLE [Ventas] ADD FOREIGN KEY ([id_canal]) REFERENCES [Canales] ([id_canal])
GO


